CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,account_id TEXT UNIQUE NOT NULL,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user' CHECK(role IN('user','admin')),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','blocked')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS wallets(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE,cdf BIGINT NOT NULL DEFAULT 0 CHECK(cdf>=0),usd_cents BIGINT NOT NULL DEFAULT 0 CHECK(usd_cents>=0));
CREATE TABLE IF NOT EXISTS cards(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE,card_number TEXT UNIQUE NOT NULL,expiry TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','blocked')));
CREATE TABLE IF NOT EXISTS transactions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,type TEXT NOT NULL,currency TEXT NOT NULL CHECK(currency IN('CDF','USD')),amount_cdf BIGINT NOT NULL DEFAULT 0,amount_usd_cents BIGINT NOT NULL DEFAULT 0,description TEXT,reference TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_users_email ON users(email);
CREATE INDEX IF NOT EXISTS idx_users_account ON users(account_id);
CREATE INDEX IF NOT EXISTS idx_tx_user ON transactions(user_id);
CREATE INDEX IF NOT EXISTS idx_tx_date ON transactions(created_at DESC);